css:
  .section {
    margin-bottom: 20px;
  }

  .print-format-container {
    font-size: 13px;
    line-height: 1.6;
    margin: 0 auto;
  }

  .header {
    text-align: center;
    margin-bottom: 25px;
  }

  .header h1 {
    font-size: 20px;
    border-bottom: 1px solid #000;
    padding-bottom: 5px;
  }
.row::after {
  content: "";
  display: table;
  clear: both;
}

.col-md-6 {
  float: left;
  width: 48%;
  margin-right: 4%;
}

.col-md-6:last-child {
  margin-right: 0;
}

.col-md-12 {
  width: 100%;
  float: left;
}


  p {
    margin: 4px 0;
  }
.med-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
    font-size: 14px;
  }

  .med-table th,
  .med-table td {
    border: 1px solid #333;
    padding: 8px;
    text-align: left;
  }

  .med-table th {
    background-color: #f0f0f0;
    font-weight: bold;
  }

  .med-table tbody tr:nth-child(even) {
    background-color: #fafafa;
  }

  .med-table td {
    vertical-align: top;
  }
